        "source": "export function init(config) {\n  const cfg = resolveConfig(config);\n  return { cooldown: cfg.initialCooldownTicks, remaining: 0, dirX: 1, dirY: 0, dashDirX: 0, dashDirY: 0 };\n}\nfunction resolveConfig(config) {\n  const c = config || {};\n  return {\n    walkingSpeed: c.walkingSpeed !== undefined ? c.walkingSpeed : 2,\n    dashDistance: c.dashDistance !== undefined ? c.dashDistance : 60,\n    cooldownTicks: c.cooldownTicks !== undefined ? c.cooldownTicks : 25,\n    initialCooldownTicks: c.initialCooldownTicks !== undefined ? c.initialCooldownTicks : 10\n  };\n}\nexport function step(state, input, config) {\n  const cfg = resolveConfig(config);\n  const s = Object.assign({}, state || {});\n  if (s.cooldown === undefined) s.cooldown = cfg.initialCooldownTicks;\n  if (s.remaining === undefined) s.remaining = 0;\n  if (s.dirX === undefined) s.dirX = 1;\n  if (s.dirY === undefined) s.dirY = 0;\n  if (s.dashDirX === undefined) s.dashDirX = 0;\n  if (s.dashDirY === undefined) s.dashDirY = 0;\n  const buttons = (input && input.buttons) || 0;\n  const ix = ((buttons & 32) ? 1 : 0) - ((buttons & 16) ? 1 : 0);\n  const iy = ((buttons & 128) ? 1 : 0) - ((buttons & 64) ? 1 : 0);\n  const dashStep = cfg.dashDistance / 8;\n  let dx = 0, dy = 0, ownsMotion = false;\n  const events = [];\n  if (s.remaining > 0) {\n    let ddx = s.dashDirX, ddy = s.dashDirY;\n    if (ddx === 0 && ddy === 0) { ddx = ix !== 0 || iy !== 0 ? ix : s.dirX; ddy = ix !== 0 || iy !== 0 ? iy : s.dirY; }\n    dx = ddx * dashStep; dy = ddy * dashStep;\n    ownsMotion = true;\n    s.remaining = s.remaining - 1;\n    if (s.remaining === 0) events.push(\"dash-end\");\n    if (ddx !== 0 || ddy !== 0) { s.dirX = ddx; s.dirY = ddy; }\n  } else if ((buttons & 1) && s.cooldown === 0) {\n    let ddx = ix, ddy = iy;\n    if (ddx === 0 && ddy === 0) { ddx = s.dirX; ddy = s.dirY; }\n    if (ddx === 0 && ddy === 0) ddx = 1;\n    s.dashDirX = ddx; s.dashDirY = ddy; s.dirX = ddx; s.dirY = ddy;\n    s.cooldown = cfg.cooldownTicks;\n    dx = ddx * dashStep; dy = ddy * dashStep;\n    ownsMotion = true;\n    s.remaining = 7;\n    events.push(\"dash-start\");\n  } else {\n    dx = ix * cfg.walkingSpeed; dy = iy * cfg.walkingSpeed;\n    if (ix !== 0 || iy !== 0) { s.dirX = ix; s.dirY = iy; }\n    if (s.cooldown > 0) s.cooldown = s.cooldown - 1;\n  }\n  s.cooldown = Math.trunc(s.cooldown); s.remaining = Math.trunc(s.remaining);\n  return { state: s, output: { ownsMotion: ownsMotion, displacement: { x: dx, y: dy }, events: events } };\n}\n",
